const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const company = typeof $json.company === 'string' ? $json.company.trim() : '';
const lossReason = typeof $json.lossReason === 'string' && $json.lossReason.trim() !== ''
  ? $json.lossReason.trim().toLowerCase()
  : 'all';
const since = typeof $json.since === 'string' ? $json.since.trim() : '';
const proposedInput = { sessionId, company, lossReason, since };
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const reasons = ['all', 'price', 'timing', 'location', 'scope', 'relationship', 'in-house', 'unknown'];
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
let error = null;

if (!uuidPattern.test(sessionId)) {
  error = { code: 'INVALID_SESSION', message: 'The lost-lead request needs a valid conversation session.' };
} else if (!reasons.includes(lossReason)) {
  error = { code: 'INVALID_REASON', message: `Loss reason must be one of: ${reasons.join(', ')}.` };
} else if (since !== '' && (!datePattern.test(since) || Number.isNaN(Date.parse(`${since}T00:00:00Z`)))) {
  error = { code: 'INVALID_SINCE', message: 'The since filter must use YYYY-MM-DD or be empty.' };
}

return {
  json: {
    valid: error === null,
    sessionId, company, lossReason, since, proposedInput,
    ...(error ? { response: { ok: false, error } } : {})
  }
};

const input = $('Validate List Input').first().json;
const rows = $input.all().map((item) => item.json);
const dataError = rows.find((row) => typeof row.error === 'string' && row.error !== '');

if (dataError) {
  return [{
    json: {
      ...input,
      response: {
        ok: false,
        error: {
          code: 'LOST_LEAD_DATA_UNAVAILABLE',
          message: 'Lost-lead data is not ready. Run 13 - SETUP - Lost Lead Data, then try again.'
        }
      }
    }
  }];
}

const companyFilter = input.company.toLowerCase();
const leads = rows
  .filter((row) => Number.isInteger(row.id))
  .filter((row) => companyFilter === '' || String(row.company ?? '').toLowerCase().includes(companyFilter))
  .filter((row) => input.lossReason === 'all' || String(row.lossReasons ?? '').split(',').map((value) => value.trim()).includes(input.lossReason))
  .filter((row) => input.since === '' || String(row.lostDate ?? '') >= input.since)
  .map((row) => ({
    leadId: String(row.leadId ?? ''),
    contactName: String(row.contactName ?? ''),
    company: String(row.company ?? ''),
    offer: String(row.offer ?? ''),
    source: String(row.source ?? ''),
    enquiryDate: String(row.enquiryDate ?? ''),
    lostDate: String(row.lostDate ?? ''),
    competitorsPresent: String(row.competitorsPresent ?? 'unknown'),
    competitorNotes: String(row.competitorNotes ?? ''),
    statedConcerns: String(row.statedConcerns ?? ''),
    lossReasons: String(row.lossReasons ?? 'unknown'),
    feedbackAskedAt: String(row.feedbackAskedAt ?? ''),
    feedbackText: String(row.feedbackText ?? ''),
    doorOpen: String(row.doorOpen ?? 'unknown'),
    nextTouch: String(row.nextTouch ?? ''),
    updatedAt: row.updatedAt
  }))
  .sort((a, b) => (a.lostDate < b.lostDate ? 1 : -1));

const reasonCounts = {};
let withCompetitors = 0;
let withFeedback = 0;
for (const lead of leads) {
  for (const reason of lead.lossReasons.split(',').map((value) => value.trim()).filter(Boolean)) {
    reasonCounts[reason] = (reasonCounts[reason] ?? 0) + 1;
  }
  if (lead.competitorsPresent === 'yes') withCompetitors += 1;
  if (lead.feedbackText !== '') withFeedback += 1;
}

return [{
  json: {
    ...input,
    response: {
      ok: true,
      leads,
      totals: {
        count: leads.length,
        byLossReason: reasonCounts,
        withCompetitorsPresent: withCompetitors,
        withFeedbackRecorded: withFeedback,
        patternNoteThreshold: 5
      },
      message: leads.length === 0
        ? 'No lost leads are recorded yet.'
        : `${leads.length} lost lead(s) on file.`
    }
  }
}];

const response = $json.response;
const proposedInput = $json.proposedInput ?? {};
return {
  json: {
    occurredAt: new Date().toISOString(),
    sessionId: String($json.sessionId ?? ''),
    requestId: String($json.actionId ?? $json.requestId ?? ''),
    toolName: 'list_lost_leads',
    proposedInput: JSON.stringify(proposedInput),
    result: JSON.stringify(response),
    error: response?.ok === false ? String(response.error?.message ?? 'Tool call failed') : '',
    response
  }
};

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
